        "direction": {
          "acceptance": [
            {
              "acceptance_id": "DIRACC-A000000000000001",
              "behavior": {
                "applicability": "required",
                "examples": [
                  {
                    "basis_refs": [
                      "direction.requirement:DIRREQ-A000000000000001",
                      "direction.requirement:DIRREQ-A000000000000007"
                    ],
                    "example_id": "DIREX-A000000000000001",
                    "given": [
                      "成员已通过可信宿主会话认证",
                      "该成员有一份待审核的本人申请"
                    ],
                    "then": [
                      "申请状态变为已撤回",
                      "产生一条审计记录（操作者、待审核→已撤回、撤回）"
                    ],
                    "title": "成员撤回本人待审核申请",
                    "when": "成员请求撤回该申请"
                  }
                ]
              },
              "requirement_refs": [
                "DIRREQ-A000000000000001",
                "DIRREQ-A000000000000003",
                "DIRREQ-A000000000000007"
              ],
              "statement": "成员撤回本人待审核申请后，状态变为已撤回，审计记录完整。"
            },
            {
              "acceptance_id": "DIRACC-A000000000000002",
              "behavior": {
                "applicability": "required",
                "examples": [
                  {
                    "basis_refs": [
                      "direction.requirement:DIRREQ-A000000000000002"
                    ],
                    "example_id": "DIREX-A000000000000002",
                    "given": [
                      "成员已认证",
                      "申请不属于该成员"
                    ],
                    "then": [
                      "撤回被拒绝",
                      "申请状态不变",
                      "不产生审计记录"
                    ],
                    "title": "撤回他人申请被拒绝",
                    "when": "成员请求撤回该申请"
                  }
                ]
              },
              "requirement_refs": [
                "DIRREQ-A000000000000002",
                "DIRREQ-A000000000000003"
              ],
              "statement": "非本人或非待审核的撤回被拒绝，申请状态不变，不产生审计记录。"
            },
            {
              "acceptance_id": "DIRACC-A000000000000003",
              "behavior": {
                "applicability": "required",
                "examples": [
                  {
                    "basis_refs": [
                      "direction.requirement:DIRREQ-A000000000000004"
                    ],
                    "example_id": "DIREX-A000000000000003",
                    "given": [
                      "申请已处于已撤回状态"
                    ],
                    "then": [
                      "返回已撤回结果",
                      "不新增审计记录"
                    ],
                    "title": "重复撤回幂等",
                    "when": "成员再次撤回该申请"
                  }
                ]
              },
              "requirement_refs": [
                "DIRREQ-A000000000000004"
              ],
              "statement": "重复撤回返回相同结果且不重复记审计。"
            },
            {
              "acceptance_id": "DIRACC-A000000000000004",
              "behavior": {
                "applicability": "required",
                "examples": [
                  {
                    "basis_refs": [
                      "direction.requirement:DIRREQ-A000000000000005"
                    ],
                    "example_id": "DIREX-A000000000000004",
                    "given": [
                      "申请处于待审核状态"
                    ],
                    "then": [
                      "只有一个操作成功",
                      "另一个被拒绝"
                    ],
                    "title": "并发撤回与审批",
                    "when": "成员撤回和负责人审批同时发生"
                  }
                ]
              },
              "requirement_refs": [
                "DIRREQ-A000000000000005"
              ],
              "statement": "撤回与审批并发时只有一个成功。"
            },
            {
              "acceptance_id": "DIRACC-A000000000000005",
              "behavior": {
                "applicability": "required",
                "examples": [
                  {
                    "basis_refs": [
                      "direction.requirement:DIRREQ-A000000000000006"
                    ],
                    "example_id": "DIREX-A000000000000005",
                    "given": [
                      "成员之前发起撤回但未收到响应"
                    ],
                    "then": [
                      "返回申请的实际当前状态"
                    ],
                    "title": "查询实际状态",
                    "when": "成员查询申请状态"
                  }
                ]
              },
              "requirement_refs": [
                "DIRREQ-A000000000000006"
              ],
              "statement": "响应丢失后可查询实际状态。"
            },
            {
              "acceptance_id": "DIRACC-A000000000000006",
              "behavior": {
                "applicability": "required",
                "examples": [
                  {
                    "basis_refs": [
                      "direction.requirement:DIRREQ-A000000000000008"
                    ],
                    "example_id": "DIREX-A000000000000006",
                    "given": [
                      "一份申请已在成员服务中撤回"
                    ],
                    "then": [
                      "运营汇总看到的状态与成员服务一致（已撤回）"
                    ],
                    "title": "统一申请身份",
                    "when": "运营汇总查询该申请状态"
                  }
                ]
              },
              "requirement_refs": [
                "DIRREQ-A000000000000008"
              ],
              "statement": "成员服务和运营汇总使用统一的申请身份和状态含义。"
            },
            {
              "acceptance_id": "DIRACC-A000000000000007",
              "behavior": {
                "applicability": "required",
                "examples": [
                  {
                    "basis_refs": [
                      "direction.requirement:DIRREQ-A000000000000009"
                    ],
                    "example_id": "DIREX-A000000000000007",
                    "given": [
                      "工具已启动"
                    ],
                    "then": [
                      "操作通过本地终端命令行完成",
                      "不通过网页或网络服务"
                    ],
                    "title": "终端交互",
                    "when": "成员执行撤回操作"
                  }
                ]
              },
              "requirement_refs": [
                "DIRREQ-A000000000000009"
              ],
              "statement": "全部交互通过本地终端完成。"
            }
