          "decision_context": {
            "assumptions": [
              {
                "reconsider_when": "上游权威已有采用修订",
                "statement": "项目尚未采用长期权威，方向确认后需要首次形成并确认产品、领域、架构和工程政策修订才能开始实施"
              },
