            "不实现已批准预约的取消。",
            "不实现缴费。",
            "不增加网页或网络服务。",
            "不增加日期转换或时区处理。",
            "本事项不交付周报能力（由另一事项单独交付）。"
          ],
          "schema_version": "strixnova.direction-decision.v1",
          "scope": [
            {
              "requirement_id": "DIRREQ-A000000000000001",
              "statement": "申请成员可撤回本人待审核的预约申请。"
